-- Wain — database schema for the admin panel.
-- Generated by scripts/gen-schema.mjs from src/lib/places.ts. Do not hand-edit;
-- re-run `npm run db:schema` instead.
--
-- Paste this whole file into the Supabase SQL editor and run it once.

-- ---------------------------------------------------------------------------
-- Who may administer the site.
--
-- Membership here — not merely "is signed in" — is what grants write access.
-- Leaving it at "any authenticated user" would mean anyone who can create an
-- account could edit the site.
-- ---------------------------------------------------------------------------
create table if not exists public.admins (
  user_id uuid primary key references auth.users (id) on delete cascade,
  email   text not null,
  added_at timestamptz not null default now()
);
alter table public.admins enable row level security;

-- Matched directly on the row, NOT via "is the asker an admin?" — a policy on
-- admins that queries admins recurses, and PostgreSQL refuses:
--   ERROR: infinite recursion detected in policy for relation "admins"
-- That error does not stay local. Every policy on places and submissions asks
-- this table whether the user is an admin, so the recursive version took the
-- whole admin panel down with it while the public site kept working.
-- Verified against PostgreSQL 16, both the failure and this fix.
--
-- Consequence worth knowing: an admin sees only their own row here, not the
-- full list. The panel only ever asks about itself, and one admin does not
-- need to enumerate the others.
drop policy if exists "admins can see the admin list" on public.admins;
drop policy if exists "an admin can see their own row" on public.admins;
create policy "an admin can see their own row"
  on public.admins for select
  using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- Places
-- ---------------------------------------------------------------------------
create table if not exists public.places (
  id             uuid primary key default gen_random_uuid(),
  slug           text unique not null check (slug ~ '^[a-z0-9-]+$'),
  name           text not null,
  name_ar        text not null,
  category       text not null check (category in
                   ('landmarks','restaurants','fastfood','coffee',
                    'outdoors','shopping','culture','family')),
  area           text not null,
  area_ar        text not null,
  lat            double precision not null check (lat between -90 and 90),
  lng            double precision not null check (lng between -180 and 180),
  rating         numeric(2,1) not null check (rating between 0 and 5),
  price_level    smallint not null check (price_level between 1 and 3),
  emoji          text not null default '📍',
  tagline_ar     text not null,
  description_ar text not null,
  highlights_ar  text[] not null default '{}',
  best_time_ar   text not null,
  -- Whether the place works at 48°C, and who it suits. See src/lib/places.ts.
  setting        text not null default 'mixed'
                   check (setting in ('indoor','outdoor','mixed')),
  season_ar      text not null default '',
  tags_ar        text[] not null default '{}' check (array_length(tags_ar, 1) is null
                                                     or array_length(tags_ar, 1) <= 30),
  -- Business profile. Null on the seeded places, so their pages are unchanged.
  logo_url       text,
  bio_ar         text not null default '',
  image_urls     text[] not null default '{}',
  -- The place's public channels, shown on its page. Website is scheme-checked
  -- so a stored value is always safe to put in an href.
  phone          text not null default '' check (length(phone) <= 40),
  instagram      text not null default '' check (length(instagram) <= 80),
  website        text not null default ''
                   check (website = '' or
                          (length(website) <= 200 and website ~* '^https?://[^[:space:]]{3,}$')),
  products_ar    text[] not null default '{}' check (array_length(products_ar, 1) is null
                                                     or array_length(products_ar, 1) <= 20),
  -- طلب مسبق. menu_ar is [{ id, nameAr, priceFils, noteAr?, soldOut? }].
  -- accepts_orders is the business's own switch: publishing a menu is not
  -- consent to take orders, and turning ordering off must not delete it.
  menu_ar        jsonb not null default '[]'::jsonb
                   check (jsonb_typeof(menu_ar) = 'array' and jsonb_array_length(menu_ar) <= 60),
  accepts_orders boolean not null default false,
  order_note_ar  text not null default '' check (length(order_note_ar) <= 300),
  featured       boolean not null default false,
  published      boolean not null default true,
  sort_order     integer not null default 0,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create index if not exists places_category_idx on public.places (category);
create index if not exists places_sort_idx     on public.places (sort_order, created_at);

-- Keep updated_at honest.
create or replace function public.touch_updated_at() returns trigger
language plpgsql as $$
begin new.updated_at = now(); return new; end $$;

drop trigger if exists places_touch on public.places;
create trigger places_touch before update on public.places
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Row level security
--
-- Visitors read published rows with the anon key and can do nothing else.
-- Every write requires an authenticated session that is also in admins.
-- ---------------------------------------------------------------------------
-- A database created before these columns existed gets them on re-run;
-- "create table if not exists" alone would silently skip them.
alter table public.places
  add column if not exists menu_ar        jsonb not null default '[]'::jsonb,
  add column if not exists accepts_orders boolean not null default false,
  add column if not exists order_note_ar  text not null default '',
  add column if not exists setting     text not null default 'mixed',
  add column if not exists season_ar   text not null default '',
  add column if not exists tags_ar     text[] not null default '{}',
  add column if not exists phone       text not null default '',
  add column if not exists instagram   text not null default '',
  add column if not exists website     text not null default '',
  add column if not exists products_ar text[] not null default '{}';
alter table public.places enable row level security;

drop policy if exists "anyone can read published places" on public.places;
create policy "anyone can read published places"
  on public.places for select
  using (published = true);

drop policy if exists "admins read every place" on public.places;
create policy "admins read every place"
  on public.places for select
  using (exists (select 1 from public.admins a where a.user_id = auth.uid()));

drop policy if exists "admins insert places" on public.places;
create policy "admins insert places"
  on public.places for insert
  with check (exists (select 1 from public.admins a where a.user_id = auth.uid()));

drop policy if exists "admins update places" on public.places;
create policy "admins update places"
  on public.places for update
  using (exists (select 1 from public.admins a where a.user_id = auth.uid()))
  with check (exists (select 1 from public.admins a where a.user_id = auth.uid()));

drop policy if exists "admins delete places" on public.places;
create policy "admins delete places"
  on public.places for delete
  using (exists (select 1 from public.admins a where a.user_id = auth.uid()));

-- ---------------------------------------------------------------------------
-- Business submissions — "سجّل مكانك"
--
-- Anyone in Kuwait can submit their business from /add/, free, without an
-- account. That means this is the one table the anon key may write to, so the
-- policies are the security boundary and are deliberately narrow:
--
--   * insert only. There is no anon select policy, so a submitter cannot read
--     back this table — not their own row, not anyone else's. Submissions carry
--     phone numbers and emails, and an open select would publish the lot.
--   * the insert check pins status to 'pending' and review fields to null, so
--     nobody can post a row that is already approved.
--   * a submission is NOT a place. Nothing here reaches the site until an admin
--     approves it, which copies the fields into public.places.
-- ---------------------------------------------------------------------------
create table if not exists public.submissions (
  id             uuid primary key default gen_random_uuid(),
  status         text not null default 'pending'
                   check (status in ('pending','approved','rejected')),

  -- the business
  name           text not null check (length(btrim(name)) between 2 and 120),
  name_ar        text not null check (length(btrim(name_ar)) between 2 and 120),
  category       text not null check (category in
                   ('landmarks','restaurants','fastfood','coffee',
                    'outdoors','shopping','culture','family')),
  area_ar        text not null check (length(btrim(area_ar)) between 2 and 80),
  address_ar     text not null default '' check (length(address_ar) <= 300),
  lat            double precision check (lat between 28.5 and 30.2),
  lng            double precision check (lng between 46.5 and 48.6),
  price_level    smallint not null default 2 check (price_level between 1 and 3),
  tagline_ar     text not null check (length(btrim(tagline_ar)) between 4 and 160),
  description_ar text not null default '' check (length(description_ar) <= 1200),

  -- how to reach the business publicly
  phone          text not null default '' check (length(phone) <= 40),
  instagram      text not null default '' check (length(instagram) <= 80),
  -- Scheme-checked at rest. Nothing renders this today, but the day someone
  -- puts it in an href, a stored 'javascript:…' becomes stored XSS. Rejecting
  -- it here means that day is safe by default rather than by remembering.
  website        text not null default ''
                   check (website = '' or
                          (length(website) <= 200 and website ~* '^https?://[^[:space:]]{3,}$')),

  -- how to reach whoever submitted it (never shown on the site)
  contact_name   text not null check (length(btrim(contact_name)) between 2 and 120),
  contact_email  text not null check (contact_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
  contact_phone  text not null default '' check (length(contact_phone) <= 40),

  -- what the business sent, as storage paths in the private bucket. Nothing
  -- here is public: an admin approves images one by one, and only the approved
  -- ones are copied into the public bucket.
  logo_path      text,
  image_paths    text[] not null default '{}' check (array_length(image_paths, 1) is null
                                                     or array_length(image_paths, 1) <= 12),
  bio_ar         text not null default '' check (length(bio_ar) <= 800),
  products_ar    text[] not null default '{}' check (array_length(products_ar, 1) is null
                                                     or array_length(products_ar, 1) <= 20),

  -- moderation
  admin_note     text not null default '',
  reviewed_at    timestamptz,
  reviewed_by    uuid references auth.users (id) on delete set null,
  published_slug text,

  created_at     timestamptz not null default now()
);

create index if not exists submissions_status_idx on public.submissions (status, created_at desc);

-- The same business submitted twice while the first is still pending is almost
-- always a double-tap on the button, not a second business.
create unique index if not exists submissions_pending_unique
  on public.submissions (lower(btrim(name_ar)), lower(btrim(area_ar)))
  where status = 'pending';

alter table public.submissions
  add column if not exists products_ar text[] not null default '{}';

-- The photo cap was raised from 8 to 12; a database created under the old
-- cap keeps its old CHECK unless it is replaced (Postgres auto-names the
-- inline constraint <table>_<column>_check).
alter table public.submissions drop constraint if exists submissions_image_paths_check;
alter table public.submissions add constraint submissions_image_paths_check
  check (array_length(image_paths, 1) is null or array_length(image_paths, 1) <= 12);

alter table public.submissions enable row level security;

drop policy if exists "anyone may submit a business" on public.submissions;
create policy "anyone may submit a business"
  on public.submissions for insert
  to anon, authenticated
  with check (
    status = 'pending'
    and reviewed_at is null
    and reviewed_by is null
    and published_slug is null
    and admin_note = ''
  );

drop policy if exists "admins read submissions" on public.submissions;
create policy "admins read submissions"
  on public.submissions for select
  using (exists (select 1 from public.admins a where a.user_id = auth.uid()));

drop policy if exists "admins update submissions" on public.submissions;
create policy "admins update submissions"
  on public.submissions for update
  using (exists (select 1 from public.admins a where a.user_id = auth.uid()))
  with check (exists (select 1 from public.admins a where a.user_id = auth.uid()));

drop policy if exists "admins delete submissions" on public.submissions;
create policy "admins delete submissions"
  on public.submissions for delete
  using (exists (select 1 from public.admins a where a.user_id = auth.uid()));

-- ---------------------------------------------------------------------------
-- ---------------------------------------------------------------------------
-- طلبات مسبقة — order ahead, pay on collection
--
-- Deliberately not a payment record. wain never takes a card and never holds
-- anyone's money: a row here is a message to a business saying "have this
-- ready at this time", and the money changes hands at their till. So there is
-- no paid flag, no amount captured, and no reconciliation to get wrong — and
-- a tampered total costs nobody anything, because the business charges from
-- its own menu and can see every line the customer was shown.
--
-- The anon key may insert and nothing else, exactly like submissions: one
-- customer must never be able to read another's phone number back out.
-- ---------------------------------------------------------------------------
create table if not exists public.orders (
  -- Supplied by the client, not defaulted here. Anon has no SELECT policy, and
  -- PostgreSQL checks the SELECT policy on any row an INSERT ... RETURNING
  -- hands back — so asking the database for the id it just generated made the
  -- whole insert roll back, and no order could ever be placed. The customer
  -- brings its own id and keeps it.
  id             uuid primary key,
  -- The customer's proof that this order is theirs. Unguessable, generated on
  -- their device, never shown to anyone else, and the only thing that lets
  -- them read the order back through order_status() below.
  track_token    text not null check (length(track_token) between 20 and 64),
  status         text not null default 'placed'
                   check (status in ('placed','ready','collected','cancelled')),

  place_slug     text not null check (place_slug ~ '^[a-z0-9-]+$'),
  -- Denormalised on purpose: the order should still read correctly if the
  -- place is later renamed, and a business reading its own orders should not
  -- need a join to know which of its branches they are for.
  place_name_ar  text not null check (length(btrim(place_name_ar)) between 2 and 120),

  -- [{ id, nameAr, priceFils, qty }] as the customer was shown them.
  lines          jsonb not null check (jsonb_typeof(lines) = 'array'
                                       and jsonb_array_length(lines) between 1 and 20),
  -- Integer fils. The dinar has three decimal places, so money is never a
  -- float here; 50 KWD is a generous ceiling for an order collected by hand.
  total_fils     integer not null check (total_fils between 0 and 50000),

  pickup_at      text not null check (pickup_at ~ '^[0-2][0-9]:[0-5][0-9]$'),
  customer_name  text not null check (length(btrim(customer_name)) between 2 and 80),
  -- Kuwaiti mobile: eight digits starting 5, 6 or 9, stored bare.
  customer_phone text not null check (customer_phone ~ '^[569][0-9]{7}$'),
  note_ar        text not null default '' check (length(note_ar) <= 200),

  admin_note     text not null default '',
  -- When each step happened, so the customer sees "جاهز من ٥ دقايق" rather
  -- than a status with no history behind it.
  ready_at       timestamptz,
  collected_at   timestamptz,
  cancelled_at   timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create index if not exists orders_place_idx on public.orders (place_slug, created_at desc);
create index if not exists orders_status_idx on public.orders (status, created_at desc);

alter table public.orders enable row level security;

-- Supabase's default privileges normally hand anon and authenticated a grant
-- on every new table in public, and everything above quietly depends on that.
-- Saying it here as well costs nothing and makes this file work on a project
-- where those defaults were tightened. A grant only opens the door; the
-- policies above are still the whole of the authorization.
grant select                         on public.places      to anon, authenticated;
grant select, insert, update, delete on public.places      to authenticated;
grant select                         on public.admins      to authenticated;
grant insert                         on public.submissions to anon, authenticated;
grant select,         update, delete on public.submissions to authenticated;
grant insert                         on public.orders      to anon, authenticated;
grant select,         update         on public.orders      to authenticated;

-- Upgrading a database created before tracking. The column arrives with an
-- empty default, which the length CHECK would reject, so existing rows are
-- given a real token first and the constraint is applied after — in that
-- order, or the ALTER fails on its own default.
alter table public.orders
  add column if not exists track_token  text not null default '',
  add column if not exists ready_at     timestamptz,
  add column if not exists collected_at timestamptz,
  add column if not exists cancelled_at timestamptz;
update public.orders set track_token = md5(random()::text || clock_timestamp()::text || id::text)
  where length(track_token) < 20;
alter table public.orders drop constraint if exists orders_track_token_check;
alter table public.orders add constraint orders_track_token_check
  check (length(track_token) between 20 and 64);
-- The id is supplied by the client now; a leftover default is harmless but
-- misleading about where it comes from.
alter table public.orders alter column id drop default;


drop policy if exists "anyone may place an order" on public.orders;
create policy "anyone may place an order"
  on public.orders for insert
  to anon, authenticated
  -- A new order is 'placed' and nothing else: without this an anon caller
  -- could insert a row already marked collected.
  with check (status = 'placed' and admin_note = ''
              and ready_at is null and collected_at is null and cancelled_at is null);

drop policy if exists "admins read every order" on public.orders;
create policy "admins read every order"
  on public.orders for select
  to authenticated
  using (exists (select 1 from public.admins a where a.user_id = auth.uid()));

drop policy if exists "admins update orders" on public.orders;
create policy "admins update orders"
  on public.orders for update
  to authenticated
  using (exists (select 1 from public.admins a where a.user_id = auth.uid()))
  with check (exists (select 1 from public.admins a where a.user_id = auth.uid()));

drop trigger if exists orders_touch on public.orders;
create trigger orders_touch before update on public.orders
  for each row execute function public.touch_updated_at();

-- The moment a status changes is recorded here rather than trusted from
-- whoever sent the update.
create or replace function public.stamp_order_status() returns trigger
  language plpgsql as $$
begin
  if new.status is distinct from old.status then
    if new.status = 'ready'     then new.ready_at     := now(); end if;
    if new.status = 'collected' then new.collected_at := now(); end if;
    if new.status = 'cancelled' then new.cancelled_at := now(); end if;
  end if;
  return new;
end $$;

drop trigger if exists orders_stamp on public.orders;
create trigger orders_stamp before update on public.orders
  for each row execute function public.stamp_order_status();

-- ---------------------------------------------------------------------------
-- Order tracking
--
-- The customer must be able to see their own order and nobody else's, without
-- an account and without opening the table up. So SELECT stays admin-only and
-- this function reaches past it — but only for someone holding both the id and
-- the token that were generated on their device when they placed the order.
--
-- It returns the state of the order and nothing that identifies the customer:
-- name and phone are deliberately absent, so even a leaked token discloses
-- only what the holder already knew.
--
-- search_path is pinned because a security definer function that resolves
-- names through the caller's search_path is a privilege escalation waiting to
-- happen.
-- ---------------------------------------------------------------------------
create or replace function public.order_status(p_id uuid, p_token text)
  returns table (
    status text,
    place_slug text,
    place_name_ar text,
    lines jsonb,
    total_fils integer,
    pickup_at text,
    note_ar text,
    created_at timestamptz,
    ready_at timestamptz,
    collected_at timestamptz,
    cancelled_at timestamptz
  )
  language sql
  security definer
  set search_path = public, pg_temp
  stable
as $$
  select o.status, o.place_slug, o.place_name_ar, o.lines, o.total_fils,
         o.pickup_at, o.note_ar, o.created_at, o.ready_at, o.collected_at,
         o.cancelled_at
  from public.orders o
  where o.id = p_id
    -- Constant-time-ish comparison is overkill for a 32-character random
    -- token, but an exact match on both columns is the whole check.
    and o.track_token = p_token
  limit 1;
$$;

revoke all on function public.order_status(uuid, text) from public;
grant execute on function public.order_status(uuid, text) to anon, authenticated;

-- Business media — logos and photos
--
-- Two buckets, because "approved" has to be a property of where a file lives,
-- not a flag someone remembers to check:
--
--   business-pending : PRIVATE. Anyone may upload here, nobody but an admin
--                      can read it. An unreviewed photo of someone's shop is
--                      not public just because its URL is hard to guess.
--   business-media   : PUBLIC. Only admins may write. A file is here only
--                      because a human approved it, so anything the site
--                      renders has been seen.
--
-- Approving copies the bytes across and records the public URL on the place.
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('business-pending', 'business-pending', false, 12582912,
   array['image/jpeg','image/png','image/webp']),
  ('business-media',   'business-media',   true,  12582912,
   array['image/jpeg','image/png','image/webp'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "anyone may upload media for review" on storage.objects;
create policy "anyone may upload media for review"
  on storage.objects for insert
  to anon, authenticated
  with check (bucket_id = 'business-pending');

drop policy if exists "admins read pending media" on storage.objects;
create policy "admins read pending media"
  on storage.objects for select
  using (bucket_id = 'business-pending'
         and exists (select 1 from public.admins a where a.user_id = auth.uid()));

drop policy if exists "admins delete pending media" on storage.objects;
create policy "admins delete pending media"
  on storage.objects for delete
  using (bucket_id = 'business-pending'
         and exists (select 1 from public.admins a where a.user_id = auth.uid()));

-- The public bucket serves reads without consulting policies; these govern who
-- may put something in it, which is the part that matters.
drop policy if exists "admins publish media" on storage.objects;
create policy "admins publish media"
  on storage.objects for insert
  to authenticated
  with check (bucket_id = 'business-media'
              and exists (select 1 from public.admins a where a.user_id = auth.uid()));

drop policy if exists "admins remove published media" on storage.objects;
create policy "admins remove published media"
  on storage.objects for delete
  using (bucket_id = 'business-media'
         and exists (select 1 from public.admins a where a.user_id = auth.uid()));

-- ---------------------------------------------------------------------------
-- Seed: the 36 places the site ships with today.
-- ---------------------------------------------------------------------------
insert into public.places
  (slug, name, name_ar, category, area, area_ar, lat, lng, rating, price_level,
   emoji, tagline_ar, description_ar, highlights_ar, best_time_ar,
   setting, season_ar, tags_ar, featured, sort_order)
values
