  ('mais-alghanim', 'Mais Alghanim', 'ميس الغانم', 'restaurants', 'Gulf Road', 'شارع الخليج', 29.3665, 48.0003, 4.6, 2, '🍢', 'مطعم كويتي عريق على شارع الخليج.', 'من أقدم وأشهر المطاعم الكويتية، معروف بالمشاوي والمقبّلات والأكل الشامي والكويتي. مكان يعرفه كل أهل الكويت، ومناسب للعزايم العائلية.', ARRAY['مشاوي ومقبّلات', 'إطلالة على شارع الخليج', 'مناسب للعوائل']::text[], 'العشاء، ويفضّل الحجز', 'indoor', 'طول السنة', ARRAY['مشاوي', 'عزايم', 'عوائل', 'شامي', 'عشا', 'حجز', 'غدا']::text[], true, 30),
