  ('salem-al-mubarak-street', 'Salem Al Mubarak Street', 'شارع سالم المبارك', 'fastfood', 'Salmiya', 'السالمية', 29.3369, 48.0664, 4.3, 1, '🍔', 'شارع الأكل السريع والسهرات في السالمية.', 'أشهر شارع في السالمية، مليان مطاعم وجبات سريعة ومحلات حلا وكافيهات. مكان الطلعة السريعة إذا تبي تاكل شي على الماشي وتتمشى بعدها.', ARRAY['برجر ووجبات سريعة', 'محلات حلا وآيس كريم', 'مفتوح لوقت متأخر']::text[], 'بالليل، بعد الثامنة', 'mixed', 'من أكتوبر لأبريل، وبالليل صيفاً', ARRAY['برجر', 'بيتزا', 'شاورما', 'سناك', 'حلا', 'آيس كريم', 'ربع', 'سهرة', 'رخيص']::text[], false, 60),
  ('the-avenues', 'The Avenues', 'الأفنيوز', 'shopping', 'Al Rai', 'الري', 29.3025, 47.937, 4.7, 3, '🛍️', 'مدينة داخل مدينة — أكبر مول في الخليج.', 'أكثر من ١١٠٠ محل موزّعة على مناطق مختلفة، كل وحدة لها طابعها. من الماركات العالمية في البرستيج إلى الجراند أفنيو اللي يشبه السوق المفتوح. يوم كامل ما يكفيه.', ARRAY['مناطق تسوّق متنوّعة', 'مطاعم عالمية', 'ممشى داخلي مكيّف']::text[], 'الصبح في أيام الدوام، عشان الزحمة', 'indoor', 'طول السنة — مكيّف بالكامل', ARRAY['مكيّف', 'ماركات', 'سينما', 'مطاعم', 'فطور', 'برجر', 'بيتزا', 'عوائل', 'مشي داخلي']::text[], false, 70),
