  ('jacc', 'Sheikh Jaber Cultural Centre', 'مركز الشيخ جابر الثقافي', 'culture', 'Kuwait City', 'مدينة الكويت', 29.3589, 48.0004, 4.8, 2, '🎭', 'دار الأوبرا في الخليج.', 'مجمّع مسارح وقاعات موسيقية بتصميم مغطّى بزخارف هندسية إسلامية. احضر أوبرا أو حفل سيمفوني، أو بس تعال شوف المعمار وهو ينعكس على المسطحات المائية.', ARRAY['عروض عالمية', 'معمار مميّز', 'إضاءة مسائية']::text[], 'ليالي العروض — احجز مقدّماً', 'indoor', 'طول السنة — مواسم العروض بالشتاء', ARRAY['مكيّف', 'أوبرا', 'حفلات', 'عمارة', 'موعد', 'راقي']::text[], false, 110),
  ('failaka-island', 'Failaka Island', 'جزيرة فيلكا', 'outdoors', 'Arabian Gulf', 'الخليج العربي', 29.4457, 48.3318, 4.4, 2, '⛵', 'آثار يونانية قديمة، على بعد رحلة عبّارة.', 'كانت موطن حضارة من العصر البرونزي وفيها قلعة هلنستية. فيلكا تجمع بين الآثار والشواطئ الهادية. خذ العبّارة من السالمية، لف على الآثار، واقعد لشواء على البحر.', ARRAY['آثار هلنستية', 'رحلات عبّارة يومية', 'شواطئ هادية']::text[], 'الربيع والشتاء، نهاية الأسبوع', 'outdoor', 'الربيع والشتاء', ARRAY['آثار', 'عبّارة', 'بحر', 'شواء', 'ربع', 'رحلة']::text[], false, 120),
  ('mirror-house', 'The Mirror House', 'بيت المرايا', 'culture', 'Qadsiya', 'القادسية', 29.3486, 47.9932, 4.6, 1, '🪞', 'بيت مغطّى بالمرايا من داخله وخارجه.', 'الفنانة ليديا القطان قضت عقود وهي تغطّي كل سطح في بيت عائلتها بفسيفساء المرايا. النتيجة وحدة من أغرب المتاحف في الشرق الأوسط، والزيارة بموعد مسبق ومع جولة شخصية.', ARRAY['غرف فسيفساء المرايا', 'جولة مع عائلة الفنانة', 'تجربة فريدة في الخليج']::text[], 'بموعد مسبق', 'indoor', 'طول السنة — بموعد مسبق', ARRAY['فن', 'تصوير', 'فريد', 'جولة', 'حجز', 'هدوء']::text[], false, 130),
