  ('tareq-rajab-museum', 'Tareq Rajab Museum', 'متحف طارق رجب', 'culture', 'Jabriya', 'الجابرية', 29.3222, 48.0231, 4.7, 1, '🏺', 'كنز خاص من الفن الإسلامي.', 'آلاف القطع من الخط العربي والخزف والمجوهرات والآلات الموسيقية، مجموعة على مدى خمسين سنة. متحف هادي ومنسّق بعناية، ومعروف إنه نجا من الغزو وهو مخبّى خلف جدار وهمي.', ARRAY['خط عربي نادر', 'مجوهرات ذهب وفضة', 'قصة مذهلة']::text[], 'عصر أيام الدوام', 'indoor', 'طول السنة', ARRAY['مكيّف', 'فن إسلامي', 'خط', 'مجوهرات', 'هدوء', 'تاريخ']::text[], false, 150),
  ('green-island', 'Green Island', 'الجزيرة الخضراء', 'family', 'Gulf Road', 'شارع الخليج', 29.3699, 48.0092, 4.2, 1, '🏝️', 'جزيرة صناعية فيها حدائق وبحيرات.', 'أول جزيرة صناعية في الخليج، مربوطة بالكورنيش بممشى. مساحات خضراء وبحيرة سباحة وبرج مشاهدة ومدرّج، تكفي لنص يوم مع العيال.', ARRAY['بحيرة سباحة', 'برج مشاهدة', 'مساحات خضراء للتنزّه']::text[], 'الأشهر الباردة، وقت العصر', 'outdoor', 'الأشهر الباردة', ARRAY['بحر', 'مشي', 'عوائل', 'تصوير', 'سباحة', 'هدوء']::text[], false, 160),
