  ('kuwait-national-museum', 'Kuwait National Museum', 'المتحف الوطني الكويتي', 'culture', 'Kuwait City', 'مدينة الكويت', 29.3737, 47.9757, 4.1, 1, '🏺', 'تاريخ الكويت وآثارها، مع قبة فلكية.', 'المتحف الوطني يجمع آثار الكويت من فيلكا والحياة البحرية والبيت الكويتي القديم، وفيه قبة فلكية. تضرّر وقت الغزو ورجع يفتح تدريجياً، وزيارته تفهّمك من وين جت الديرة.', ARRAY['آثار فيلكا', 'القبة الفلكية', 'بوم الغوص في الساحة']::text[], 'الصبح في أيام الأسبوع', 'indoor', 'طول السنة', ARRAY['مكيّف', 'تاريخ', 'آثار', 'قبة فلكية', 'عوائل', 'عيال']::text[], false, 200),
